const recordDefinitions={contract:{title:'Vertragsabschluss erfassen',copy:'Nur ein unterschriebener Vertrag mit Vertragsdokument und Videovertrag erzeugt automatisch einen Teilnehmer.',fields:`<label class="wide">Vertragsbezeichnung<input name="title" required placeholder="Finde dein Ding · 8-Wochen-Programm"></label><label>Vertragsnummer<input name="contractNumber" placeholder="FDD-2026-001"></label><label>Betrag in Euro<input name="amount" type="number" min="0" step="0.01" required></label><label>Status<select name="status"><option value="draft">Entwurf</option><option value="sent">Versendet</option><option value="signed">Unterschrieben</option><option value="cancelled">Storniert</option></select></label><label>Programmstart<input name="programStartDate" type="date" required></label><fieldset class="wide lead-contract-confirmations"><legend>Verbindliche Abschlussnachweise</legend><label><input name="documentConfirmed" type="checkbox" value="true"> Vertragsdokument vollständig unterzeichnet</label><label><input name="videoContractConfirmed" type="checkbox" value="true"> Videovertrag vollständig durchgeführt</label></fieldset>`},payment:{title:'Zahlungseingang erfassen',copy:'Der gebuchte Betrag wird mit dem Vertragsvolumen abgeglichen.',fields:`<label>Betrag in Euro<input name="amount" type="number" min="0.01" step="0.01" required></label><label>Buchungsdatum<input name="bookedAt" type="date" required></label><label class="wide">Verwendungszweck / Referenz<input name="reference" placeholder="FDD-2026-001"></label>`},communication:{title:'E-Mail protokollieren',copy:'Manueller Eintrag für den nachvollziehbaren Kommunikationsverlauf.',fields:`<label>Richtung<select name="direction"><option value="outbound">Ausgang</option><option value="inbound">Eingang</option><option value="system">System</option></select></label><label class="wide">Betreff<input name="subject" required></label><label class="wide">Vorschau<textarea name="preview"></textarea></label>`},task:{title:'Aufgabe anlegen',copy:'Interne Aufgaben stehen gemeinsam mit den Fragen aus dem Kundenprozess.',fields:`<label class="wide">Aufgabe<input name="title" required></label><label>Fällig am<input name="dueAt" type="date"></label><label class="wide">Details<textarea name="details"></textarea></label>`},bank:{title:'Bankverbindung bearbeiten',copy:'Die Daten dienen dem manuellen Abgleich eingehender Überweisungen.',fields:`<label class="wide">Kontoinhaber<input name="accountHolder"></label><label class="wide">IBAN<input name="iban"></label><label>BIC<input name="bic"></label><label class="wide">Verwendungszweck<input name="paymentReference"></label>`},note:{title:'Interne Notizen bearbeiten',copy:'Diese Notizen sind ausschließlich für Administratoren sichtbar.',fields:`<label class="wide">Notizen<textarea name="notes"></textarea></label>`}};
function openLeadRecord(type){const definition=recordDefinitions[type];if(!definition||!activeLeadDashboard)return;leadRecordForm.reset();leadRecordForm.elements.recordType.value=type;document.querySelector('#leadRecordTitle').textContent=definition.title;document.querySelector('#leadRecordCopy').textContent=definition.copy;document.querySelector('#leadRecordFields').innerHTML=definition.fields;if(type==='payment')leadRecordForm.elements.bookedAt.value=browserDateKey();if(type==='contract')leadRecordForm.elements.programStartDate.value=browserDateKey();if(type==='note')leadRecordForm.elements.notes.value=activeLeadDashboard.lead.internal_notes||'';if(type==='bank'&&activeLeadDashboard.bankAccount){const bank=activeLeadDashboard.bankAccount;leadRecordForm.elements.accountHolder.value=bank.account_holder||'';leadRecordForm.elements.iban.value=bank.iban||'';leadRecordForm.elements.bic.value=bank.bic||'';leadRecordForm.elements.paymentReference.value=bank.payment_reference||'';}leadRecordDialog.showModal();}
async function saveLeadDashboardRecord(payload){const id=activeLeadDashboard?.lead?.id;if(!id)throw new Error('Keine Interessentenakte geöffnet.');const response=await fetch('/api/leads?action=dashboard-record',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id,...payload})}),data=await response.json();if(!response.ok)throw new Error(data.error);await loadLeadDashboard(id);return data;}
document.querySelector('#closeLeadDashboard').addEventListener('click',closeLeadDashboard);document.querySelector('#editLeadProfile').addEventListener('click',()=>openLeadEditor(activeLeadDashboard?.lead?.id));document.querySelector('#openLeadSalesCall').addEventListener('click',()=>openLeadEditor(activeLeadDashboard?.lead?.id));document.querySelector('#leadDashboardConvert').addEventListener('click',()=>activeLeadDashboard?.lead?.converted_user_profile_id?openLeadEditor(activeLeadDashboard.lead.id):openLeadRecord('contract'));document.querySelectorAll('[data-lead-edit="profile"]').forEach(button=>button.addEventListener('click',()=>openLeadEditor(activeLeadDashboard?.lead?.id)));document.querySelectorAll('[data-lead-record]').forEach(button=>button.addEventListener('click',()=>openLeadRecord(button.dataset.leadRecord)));document.querySelectorAll('[data-close-lead-record]').forEach(button=>button.addEventListener('click',()=>leadRecordDialog.close()));document.querySelectorAll('[data-lead-task-filter]').forEach(button=>button.addEventListener('click',()=>{leadTaskFilter=button.dataset.leadTaskFilter;document.querySelectorAll('[data-lead-task-filter]').forEach(item=>item.classList.toggle('active',item===button));renderLeadTasks();}));leadRecordForm.addEventListener('submit',async event=>{event.preventDefault();const button=leadRecordForm.querySelector('[type="submit"]');button.disabled=true;try{const payload=Object.fromEntries(new FormData(leadRecordForm));const result=await saveLeadDashboardRecord(payload);leadRecordDialog.close();if(result.participantActivated){await Promise.all([loadParticipants(),loadLeads(),loadUsers()]);toast('Vertragsabschluss vollständig: Der Lead wurde automatisch als Teilnehmer aktiviert.');}else toast('Akte wurde aktualisiert.');}catch(error){toast(error.message);}finally{button.disabled=false;}});
async function saveLead(showMessage=true){const response=await fetch('/api/leads?action=update',{method:'PATCH',headers:{'Content-Type':'application/json'},body:JSON.stringify(leadPayload())});const data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);renderLeadDialog(data.lead);if(showMessage)toast('Interessent wurde gespeichert.');return data.lead;}
leadForm.addEventListener('submit',async event=>{event.preventDefault();try{await saveLead();await loadLeads();if(activeLeadDashboard)await loadLeadDashboard();}catch(error){toast(error.message);}});
document.querySelector('#refreshSlots').addEventListener('click',loadAvailableSlots);
document.querySelector('#slotRangeStart').addEventListener('change',loadAvailableSlots);
leadForm.elements.appointmentDuration.addEventListener('change',()=>{leadForm.elements.appointmentStart.value='';showSelectedSlot('');loadAvailableSlots();});
document.querySelector('#scheduleLead').addEventListener('click',async()=>{const button=document.querySelector('#scheduleLead'),start=leadForm.elements.appointmentStart.value,duration=Number(leadForm.elements.appointmentDuration.value);if(!start)return toast('Bitte einen angezeigten freien Termin auswählen.');button.disabled=true;try{const saved=await saveLead(false);const response=await fetch('/api/leads?action=schedule',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:saved.id,start:new Date(start).toISOString(),duration})});const data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);renderLeadDialog(data.lead);toast('Kalendertermin und Google Meet wurden erstellt.');await loadLeads();if(activeLeadDashboard)await loadLeadDashboard();}catch(error){toast(error.message);}finally{button.disabled=false;}});
document.querySelector('#cancelLeadAppointment').addEventListener('click',async()=>{if(!confirm('Termin wirklich absagen? Google informiert den eingeladenen Interessenten.'))return;try{const response=await fetch('/api/leads?action=cancel-appointment',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({id:leadForm.elements.id.value})});const data=await response.json();if(!response.ok)throw new Error(data.error);updateLeadCache(data.lead);renderLeadDialog(data.lead);toast('Termin wurde abgesagt.');await loadLeads();if(activeLeadDashboard)await loadLeadDashboard();}catch(error){toast(error.message);}});
const systemStatusLabels={active:'Aktiv',ready:'Bereit zur Verbindung',missing:'Konfiguration fehlt',planned:'Geplant'};
function systemStatusBadge(item){const key=item.status?.key||'missing';return `<span class="system-status-badge ${escapeHtml(item.status?.tone||'danger')}"><i></i>${escapeHtml(item.status?.label||systemStatusLabels[key]||key)}</span>`;}
function renderIntegrationRegistry(items=[]){const grid=document.querySelector('#integrationStatusGrid');if(!grid)return;grid.innerHTML=items.length?items.map(item=>`<article class="system-registry-card ${escapeHtml(item.status?.tone||'neutral')}"><div class="system-registry-head"><span class="system-tool-icon tool-${escapeHtml(item.id)}">${escapeHtml(item.icon)}</span>${systemStatusBadge(item)}</div><small>${escapeHtml(item.category)}</small><h4>${escapeHtml(item.name)}</h4><p>${escapeHtml(item.purpose)}</p><div class="system-detail">${escapeHtml(item.detail)}</div>${item.action==='google-connect'?`<button class="secondary system-connect-action" type="button" data-system-action="google-connect">${item.status?.key==='active'?'Google neu verbinden':'Google verbinden'}</button>`:''}</article>`).join(''):'<div class="empty">Keine Schnittstellen registriert.</div>';}
function renderAgentRegistry(items=[]){const grid=document.querySelector('#agentStatusGrid');if(!grid)return;grid.innerHTML=items.length?items.map(item=>`<article class="agent-registry-card ${escapeHtml(item.status?.tone||'neutral')}"><div class="agent-registry-top"><span class="agent-avatar">${escapeHtml(item.icon)}</span><div><small>${escapeHtml(item.phase)}</small><h4>${escapeHtml(item.name)}</h4></div>${systemStatusBadge(item)}</div><p>${escapeHtml(item.situation)}</p><dl><div><dt>Werkzeug</dt><dd>${escapeHtml(item.tool)}</dd></div><div><dt>Betriebshinweis</dt><dd>${escapeHtml(item.detail)}</dd></div></dl></article>`).join(''):'<div class="empty">Keine KI-Agenten registriert.</div>';}
async function loadSystemStatus(){const refresh=document.querySelector('#systemStatusRefresh');if(refresh)refresh.disabled=true;try{const response=await fetch('/api/leads?action=system-status'),data=await response.json();if(!response.ok)throw new Error(data.error);renderIntegrationRegistry(data.integrations);renderAgentRegistry(data.agents);document.querySelector('#activeIntegrationCount').textContent=`${data.summary.activeIntegrations} / ${data.summary.totalIntegrations}`;document.querySelector('#activeAgentCount').textContent=`${data.summary.activeAgents} / ${data.summary.totalAgents}`;document.querySelector('#plannedSystemCount').textContent=String(data.summary.planned);document.querySelector('#systemCheckedAt').textContent=new Date(data.checkedAt).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'});const connected=data.integrations.filter(item=>item.status.key==='active').length;document.querySelector('#integrationRegistryState').textContent=`${connected} aktiv`;document.querySelector('#integrationRegistryState').classList.toggle('active',connected>0);const activeAgents=data.agents.filter(item=>item.status.key==='active').length;document.querySelector('#agentRegistryState').textContent=`${activeAgents} aktiv`;document.querySelector('#agentRegistryState').classList.toggle('active',activeAgents>0);}catch(error){const message=escapeHtml(error.message||'Systemstatus konnte nicht geladen werden.');document.querySelector('#integrationStatusGrid').innerHTML=`<div class="empty system-error">${message}</div>`;document.querySelector('#agentStatusGrid').innerHTML=`<div class="empty system-error">${message}</div>`;document.querySelector('#integrationRegistryState').textContent='Prüfung fehlgeschlagen';document.querySelector('#agentRegistryState').textContent='Prüfung fehlgeschlagen';}finally{if(refresh)refresh.disabled=false;}}
document.querySelector('#systemStatusRefresh')?.addEventListener('click',loadSystemStatus);
document.querySelector('#integrationStatusGrid')?.addEventListener('click',event=>{if(event.target.closest('[data-system-action="google-connect"]'))location.href='/api/google/connect';});
async function loadLeads(){try{const response=await fetch('/api/leads');const data=await response.json();if(!response.ok)throw new Error(data.error);leads=data.leads;document.querySelector('#leadRows').innerHTML=leads.length?leads.map(lead=>`<div class="table-data lead-row" data-lead-id="${escapeHtml(lead.id)}"><div class="participant"><span class="avatar">${escapeHtml(lead.name.slice(0,2).toUpperCase())}</span><div><strong>${escapeHtml(lead.name)}</strong><small>${escapeHtml(lead.email)}</small></div></div><span>${escapeHtml(lead.utm_source||lead.source)}</span><span>${escapeHtml(leadStatusLabels[lead.status]||lead.status)}</span><span>${new Date(lead.created_at).toLocaleDateString('de-DE')}</span><button class="lead-next" data-open-lead="${escapeHtml(lead.id)}">${lead.appointment_start?`${new Date(lead.appointment_start).toLocaleDateString('de-DE')} · ${new Date(lead.appointment_start).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}`:'Dashboard öffnen →'}</button></div>`).join(''):'<div class="empty">Noch keine Interessenten vorhanden.</div>';document.querySelectorAll('[data-open-lead]').forEach(button=>button.addEventListener('click',event=>{event.stopPropagation();openLeadDashboard(button.dataset.openLead);}));document.querySelectorAll('.lead-row').forEach(row=>row.addEventListener('click',()=>openLeadDashboard(row.dataset.leadId)));}catch(error){document.querySelector('#leadRows').innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`;}}
async function loadUsers(){try{const response=await fetch('/api/users');const data=await response.json();if(!response.ok)throw new Error(data.error);users=data.users;const permissionLabels={customer_portal:'Kundenportal',clara_program:'Clara',documents:'Dokumente',community:'Community'};document.querySelector('#userRows').innerHTML=users.length?users.map(user=>{const progress=user.participant_progress?.[0];return `<div class="table-data"><div class="participant"><span class="avatar">${escapeHtml(user.name.slice(0,2).toUpperCase())}</span><div><strong>${escapeHtml(user.name)}</strong><small>${escapeHtml(user.email)}</small></div></div><span class="user-meta"><b>${user.role==='admin'?'Admin':'Benutzer'}</b><small>${user.status==='active'?'Aktiv':'Deaktiviert'}</small></span><span class="access-tags">${user.role==='admin'?'<i>Alle Rechte</i>':(user.permissions||[]).map(permission=>`<i>${escapeHtml(permissionLabels[permission]||permission)}</i>`).join('')||'<i>Keine Zugänge</i>'}</span><span class="user-meta"><b>${progress?`Woche ${progress.current_week}`:'—'}</b><small>${escapeHtml(progress?.program_status||'Kein Programm')}</small></span><button class="user-manage" data-edit-user="${escapeHtml(user.id)}">Bearbeiten →</button></div>`;}).join(''):'<div class="empty">Noch keine Benutzer vorhanden.</div>';document.querySelectorAll('[data-edit-user]').forEach(button=>button.addEventListener('click',()=>openUserEdit(button.dataset.editUser)));}catch(error){document.querySelector('#userRows').innerHTML=`<div class="empty">${escapeHtml(error.message)}</div>`;}}
document.querySelector('#logout').addEventListener('click',async()=>{await fetch('/api/auth?action=session',{method:'DELETE'});location.replace('/login');});
const adminParams=new URLSearchParams(location.search);if(adminParams.get('view')&&titles[adminParams.get('view')])showView(adminParams.get('view'));if(adminParams.get('section'))showSettingsPanel(adminParams.get('section'));if(adminParams.get('google')==='connected')toast('Google Calendar wurde erfolgreich verbunden.');else if(adminParams.get('google')==='error')toast('Google-Verbindung wurde abgebrochen.');if(location.search)history.replaceState(null,'',location.pathname);
fetch('/api/auth?action=session').then(response=>{if(!response.ok)location.replace('/login');else Promise.all([loadParticipants(),loadLeads(),loadUsers(),loadSystemStatus(),loadGateSettings(),loadBookingSettings().catch(error=>toast(error.message))]);});renderParticipants();
